$p=new PDO($c['dsn'],$c['db_user'],$c['db_password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$p->beginTransaction();$find=$p->prepare('SELECT p.id,p.latitude,p.longitude FROM points_of_interest p JOIN destinations d ON p.destination_id=d.id WHERE d.slug=? AND p.slug=? AND p.publication_status<>\'archived\'');$upd=$p->prepare('UPDATE points_of_interest SET latitude=?,longitude=? WHERE id=?');$maps=$p->prepare('UPDATE point_of_interest_translations SET map_url=? WHERE point_of_interest_id=? AND locale=?');$result=[];
